  adFree: { flexDirection: 'row', alignItems: 'center', gap: 4, borderWidth: 1, borderColor: C.cyan, borderRadius: 14, paddingVertical: 4, paddingHorizontal: 9 },
  adFreeT: { color: C.cyan, fontSize: 12, fontWeight: '700' },
