  // hero
  hero: { borderRadius: 26, overflow: 'hidden', borderWidth: 1, borderColor: C.purple },
  slide: { height: 172, padding: 18, flexDirection: 'row', alignItems: 'center' },
  hA: { color: C.text, fontSize: 18, fontWeight: '600' },
  hB: { color: C.pink, fontSize: 30, fontWeight: '900', marginBottom: 2 },
  hC: { color: C.text, fontSize: 14, marginBottom: 12 },
  hBtn: { flexDirection: 'row', alignItems: 'center', gap: 8, alignSelf: 'flex-start', borderRadius: 22, paddingVertical: 9, paddingHorizontal: 16 },
  hBtnT: { color: '#fff', fontWeight: '800' },
  heroArt: { width: 128, height: 128, borderRadius: 26, borderWidth: 1, borderColor: C.violet },
  dots: { position: 'absolute', bottom: 8, left: 0, right: 0, flexDirection: 'row', justifyContent: 'center', gap: 8 },
  dot: { width: 8, height: 8, borderRadius: 4, backgroundColor: '#5b6aa8' },
  dotOn: { backgroundColor: C.pink },

  // quick access
  secRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: 18, marginBottom: 10 },
  secL: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  secT: { color: C.text, fontSize: 20, fontWeight: '700' },
  see: { color: C.pink, fontWeight: '700', fontSize: 14 },
  tiles: { flexDirection: 'row', gap: 10 },
  tile: { flex: 1, height: 86, borderRadius: 18, borderWidth: 1, overflow: 'hidden', alignItems: 'center', justifyContent: 'center', gap: 3 },
  tileT: { color: C.text, fontSize: 13, fontWeight: '600' },
  tileS: { color: C.text, fontSize: 12, marginTop: -3 },

  // panels
  panel: { backgroundColor: C.card, borderRadius: 22, borderWidth: 1, borderColor: C.line, padding: 12 },
  panelHead: { flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 10 },
  panelT: { color: C.text, fontSize: 18, fontWeight: '700', flex: 1 },

  // now playing
  np: { flexDirection: 'row', alignItems: 'center' },
  npArt: { width: 104, height: 104, borderRadius: 16, overflow: 'hidden', backgroundColor: '#000' },
  npTitle: { color: C.text, fontSize: 16, fontWeight: '700' },
  npCtl: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: 2 },
  npPlay: { width: 48, height: 48, borderRadius: 24, alignItems: 'center', justifyContent: 'center' },

  // progress
  pgHit: { height: 30, justifyContent: 'center' },
  pgTrack: { height: 5, borderRadius: 3, backgroundColor: '#2a1f4d', overflow: 'hidden' },
  pgFill: { height: 5, backgroundColor: C.pink },
  pgKnob: { position: 'absolute', top: 7, width: 16, height: 16, borderRadius: 8, backgroundColor: '#fff' },
  pgTimes: { flexDirection: 'row', justifyContent: 'space-between' },
  pgT: { color: C.dim, fontSize: 12 },

  // library / lists
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginBottom: 10 },
  chip: { backgroundColor: '#1d1538', borderRadius: 18, paddingVertical: 9, paddingHorizontal: 16 },
  chipSm: { backgroundColor: '#1d1538', borderRadius: 14, paddingVertical: 6, paddingHorizontal: 12 },
  chipOn: { backgroundColor: C.purple },
  chipT: { color: '#fff', fontWeight: '600' },
  row: { flexDirection: 'row', gap: 10, marginBottom: 8 },
  search: { flex: 1, backgroundColor: '#17102e', color: C.text, borderRadius: 14, paddingHorizontal: 14, height: 42 },
  pill: { backgroundColor: '#c026d3', borderRadius: 20, paddingVertical: 10, paddingHorizontal: 18 },
  pillSm: { backgroundColor: '#c026d3', borderRadius: 16, paddingHorizontal: 14, justifyContent: 'center', alignItems: 'center', height: 42 },
  pillT: { color: '#fff', fontWeight: '700' },
  speed: { backgroundColor: '#2a1f4d', borderRadius: 14, paddingHorizontal: 14, height: 36, justifyContent: 'center' },
  item: { flexDirection: 'row', alignItems: 'center', gap: 12, padding: 10, borderRadius: 14 },
  cur: { backgroundColor: '#1a1233' },
  badge: { width: 48, height: 48, borderRadius: 12, backgroundColor: C.purple, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },
  name: { color: C.text, fontWeight: '600', fontSize: 15 },
