  card: { flex: 1, padding: 8, borderRadius: 14, marginBottom: 8 },
  thumb: { aspectRatio: 16 / 10, borderRadius: 12, backgroundColor: C.purple, overflow: 'hidden', alignItems: 'center', justifyContent: 'center', marginBottom: 6 },
  gridHeart: { position: 'absolute', top: 6, right: 6, backgroundColor: 'rgba(0,0,0,0.5)', borderRadius: 14, padding: 4 },
